// Failed geometry pilot stays outside the live renderer until separately approved.
export function createHDPreviewOverlay({getGame}) {
  let panel=null,frame=null,openedGame=null,previouslyPaused=false,restoreFocus=null,word='';
  const style=document.createElement('style');style.textContent='.hd-preview-overlay{position:absolute;inset:0;z-index:90;background:#080807f7;color:#eee8d5;display:flex;flex-direction:column;gap:10px;padding:max(14px,env(safe-area-inset-top)) max(14px,env(safe-area-inset-right)) max(14px,env(safe-area-inset-bottom)) max(14px,env(safe-area-inset-left));overflow:auto}.hd-preview-overlay[hidden]{display:none}.hd-preview-header{display:flex;align-items:center;justify-content:space-between;gap:12px}.hd-preview-header h2{font:700 20px monospace;margin:0}.hd-preview-header button{min-height:44px;padding:8px 18px;background:#29251a;border:1px solid #88784b;color:#fff}.hd-preview-overlay p{font:13px/1.5 sans-serif;color:#d2c7aa;margin:0}.hd-preview-overlay iframe{display:block;flex:1;min-height:300px;width:100%;border:1px solid #625b43;background:#111}.hd-preview-status{font-size:12px!important}';document.head.append(style);
  function available(){const g=getGame();return !!(g?.started&&!['title','password'].includes(g.sequence?.kind));}
  function keyboard(event){if(event.code==='Escape'){event.preventDefault();event.stopPropagation();close();return;}if(/^[a-z]$/i.test(event.key)){word=(word+event.key.toUpperCase()).slice(-2);if(word==='HD'){event.preventDefault();close();word='';}}event.stopPropagation();}
  function build(){panel=document.createElement('section');panel.className='hd-preview-overlay';panel.hidden=true;panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label','HD pilot, samostatná ukázka');panel.innerHTML='<div class="hd-preview-header"><h2>HD pilot · ukázka</h2><button data-hd-close>Zavřít</button></div><p>Pilot zatím nesplnil přesnost geometrie a není schválený pro živou hru. Hra dál používá původní grafiku; zde je pouze porovnání scény a jedné animace.</p><p class="hd-preview-status" role="status">Načítání místní ukázky…</p>';document.querySelector('#game-shell').append(panel);panel.querySelector('[data-hd-close]').addEventListener('click',()=>close());panel.addEventListener('keydown',keyboard);}
  function open(){if(!available())return false;if(!panel)build();if(!panel.hidden)return true;const g=getGame();g.levelOverlay?.close();g.mapOverlay?.close();openedGame=g;previouslyPaused=!!g.paused;restoreFocus=document.activeElement;word='';if(!g.paused)g.pause();g.input?.clear();panel.hidden=false;panel.querySelector('.hd-preview-status').textContent='Načítání místní ukázky…';frame=document.createElement('iframe');frame.title='Původní grafika a neschválený HD pilot';frame.src='/hd-pilot.html';frame.addEventListener('load',()=>{try{frame.contentWindow.addEventListener('keydown',keyboard);}catch{};});panel.append(frame);panel.querySelector('[data-hd-close]').focus();return true;}
  function onMessage(event){if(!frame||event.origin!==location.origin||event.source!==frame.contentWindow)return;if(event.data?.type==='hd-pilot-ready')panel.querySelector('.hd-preview-status').textContent='Samostatný náhled. Původní hra zůstává pozastavená a její grafika se nemění.';}
  window.addEventListener('message',onMessage);
  function close({resume=true,focus=true}={}){if(!panel||panel.hidden)return;panel.hidden=true;try{frame?.contentWindow?.postMessage({type:'hd-pilot-dispose'},location.origin);}catch{}frame?.remove();frame=null;const g=openedGame;openedGame=null;g?.input?.clear();if(resume&&g&&!previouslyPaused&&g.paused)g.pause();if(focus)restoreFocus?.focus?.({preventScroll:true});}
  function dispose(){close({resume:false,focus:false});window.removeEventListener('message',onMessage);panel?.remove();style.remove();}
  return{open,close,toggle:()=>panel&&!panel.hidden?(close(),false):open(),available,dispose,get isOpen(){return !!panel&&!panel.hidden;}};
}
